-- Bloque 41 · Migración de Maca desde su Excel (programa Ciclo 1 de 5 días + mediciones de control). Se puede repetir.

do $$
declare alu uuid; n int; prog bigint; dia bigint; blq bigint; faltan text;
begin
  select count(*) into n from perfiles where nombre ilike 'maca%';
  if n <> 1 then raise exception 'Se esperaba 1 alumna llamada Maca y hay %. Crea o renombra su perfil (Maca) y repite.', n; end if;
  select id into alu from perfiles where nombre ilike 'maca%';

  -- Biblioteca: los ejercicios que no existan se crean (sin foto; ponla después desde el editor)
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Apertura de cadera'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Apertura de cadera'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Apertura de espalda'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Apertura de espalda'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Bíceps martillo en polea'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Bíceps martillo en polea'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Cierre de cadera'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Cierre de cadera'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Crunch abdominal en bosu'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Crunch abdominal en bosu'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Crunch en máquina'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Crunch en máquina'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Crunch lateral con peso libre'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Crunch lateral con peso libre'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Crunch lateral en banco inclinado'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Crunch lateral en banco inclinado'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Curl femoral sentado'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Curl femoral sentado'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Elevaciones inferiores'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Elevaciones inferiores'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Elevaciones laterales'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Elevaciones laterales'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Extensión de cadera en polea'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Extensión de cadera en polea'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Extensión de cadera inclinado'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Extensión de cadera inclinado'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Extensión de rodilla'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Extensión de rodilla'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Face pull'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Face pull'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Flexo-extensión de tobillos'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Flexo-extensión de tobillos'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Hip thrust en máquina'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Hip thrust en máquina'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Hip thrust unilateral'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Hip thrust unilateral'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Hombro posterior a 1 mano'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Hombro posterior a 1 mano'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Jalón al pecho'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Jalón al pecho'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Leg press 45º'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Leg press 45º'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Peso muerto a 1 pierna'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Peso muerto a 1 pierna'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Press de hombro a 1 mano'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Press de hombro a 1 mano'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Press militar prono'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Press militar prono'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Pull over en polea'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Pull over en polea'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Remo a 1 mano'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Remo a 1 mano'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Rotación en polea'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Rotación en polea'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Sentadilla búlgara'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Sentadilla búlgara'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Sentadilla perfecta'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Sentadilla perfecta'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Sentadilla sumo'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Sentadilla sumo'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Sprinter en polea'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Sprinter en polea'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Step up en máquina'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Step up en máquina'); end if;
  if not exists (select 1 from ejercicios where translate(lower(nombre), 'áéíóúü', 'aeiouu') = translate(lower('Tríceps tras nuca en polea'), 'áéíóúü', 'aeiouu')) then insert into ejercicios (nombre) values ('Tríceps tras nuca en polea'); end if;
  update programas set activo = false where alumno_id = alu;
  select id into prog from programas where alumno_id = alu and nombre = 'Ciclo 1 · Entrenamiento' order by id limit 1;
  if prog is null then insert into programas (alumno_id, nombre, dias_semana, activo, ciclo) values (alu, 'Ciclo 1 · Entrenamiento', 5, true, 1) returning id into prog; end if;
  update programas set dias_semana = 5, activo = true, ciclo = 1 where id = prog;
  delete from dias where programa_id = prog;

  -- Control y evolución (Excel: hoja CONTROL)
  if not exists (select 1 from mediciones where alumno_id = alu and fecha = '2026-09-10' and coalesce(es_objetivo, false) = false) then insert into mediciones (alumno_id, fecha, peso, grasa_pct, cuello, cintura, abd_bajo, cadera, brazo_d, brazo_i, hombros, muslo_d, muslo_i, gemelo_d, gemelo_i) values (alu, '2026-09-10', 78, 35, 36, 89, 97, 104, 32, 32, 57, 55, 56, 36, 36); end if;
  if not exists (select 1 from mediciones where alumno_id = alu and fecha = '2026-10-07' and coalesce(es_objetivo, false) = false) then insert into mediciones (alumno_id, fecha, peso, grasa_pct, cuello, cintura, abd_bajo, cadera) values (alu, '2026-10-07', 76.6, 34.8, 35, 86, 92, 106); end if;
  if not exists (select 1 from mediciones where alumno_id = alu and es_objetivo) then insert into mediciones (alumno_id, es_objetivo, fecha, peso, grasa_pct, nota) values (alu, true, '2026-12-10', 69, 24, 'Recomposición corporal: bajar del 35 % al 24 % de grasa (unos 9 kg menos de grasa) tonificando el músculo. Meta de la hoja: diciembre.'); end if;
end $$;
